builder.Services.AddHttpClient<IMaintenanceStaffDirectory,MaintenanceStaffDirectory>((sp,http)=>{
    http.BaseAddress=FleetFlow.ServiceDefaults.ServiceEndpoints.Identity(builder.Configuration,builder.Environment);http.Timeout=TimeSpan.FromSeconds(5);
}).ConfigurePrimaryHttpMessageHandler(()=>new HttpClientHandler{AllowAutoRedirect=false});
builder.Services.AddScoped<IBookingService, BookingService>();
builder.Services.AddSingleton(RentalRouting.Read(builder.Configuration,builder.Environment));
builder.Services.AddScoped<RentalForwarder>();builder.Services.AddScoped<ReservationService>();
builder.Services.AddHttpClient("RentalService",(sp,c)=>{c.BaseAddress=sp.GetRequiredService<RentalRouting>().BaseUrl;c.Timeout=TimeSpan.FromSeconds(5);})
.ConfigurePrimaryHttpMessageHandler(()=>new HttpClientHandler{AllowAutoRedirect=false});
builder.Services.AddSingleton(NotificationRouting.Read(builder.Configuration,builder.Environment));
builder.Services.AddScoped<NotificationForwarder>();
builder.Services.AddHttpClient("NotificationService",(sp,client)=>
{ client.BaseAddress=sp.GetRequiredService<NotificationRouting>().BaseUrl;client.Timeout=TimeSpan.FromSeconds(5); })
.ConfigurePrimaryHttpMessageHandler(()=>new HttpClientHandler{AllowAutoRedirect=false});
builder.Services.AddSingleton<IReliableNotificationPublisher,ReliableNotificationPublisher>();
builder.Services.AddScoped<NotificationService>();
builder.Services.AddScoped<NotificationEventProcessor>();
builder.Services.AddScoped<IReportingService, ReportingService>();
builder.Services.AddScoped<IMaintenanceReportSource, MaintenanceReportSource>();
builder.Services.AddSingleton<TimeProvider>(TimeProvider.System);
builder.Services.AddSingleton<FleetReadiness>();

// Configure Apache Kafka Messaging
builder.Services.Configure<KafkaSettings>(builder.Configuration.GetSection(KafkaSettings.SectionName));
builder.Services.AddSingleton<IKafkaProducerService, KafkaProducerService>();
builder.Services.AddHostedService<VehicleEventConsumerService>();
builder.Services.AddSingleton<NotificationEventDispatcher>();
builder.Services.AddSingleton<INotificationEventDispatcher>(sp => sp.GetRequiredService<NotificationEventDispatcher>());
builder.Services.AddHostedService(sp => sp.GetRequiredService<NotificationEventDispatcher>());
builder.Services.AddHostedService<NotificationEventConsumerService>();

// Configure JWT Authentication
var jwtSection = builder.Configuration.GetSection("Jwt");
var jwtKey = FleetService.Api.Security.JwtSigningKey.Resolve(builder.Configuration, builder.Environment);
FleetFlow.ServiceDefaults.ServiceAuthentication.AddInternalServiceAuthentication(builder.Services, builder.Configuration, jwtKey);
FleetFlow.ServiceDefaults.ServiceAuthentication.AddServiceTokenClient(builder.Services, builder.Configuration, builder.Environment, "fleet-service");
FleetFlow.ServiceDefaults.AccountAccessRegistration.AddRemoteAccountAccess(builder.Services,builder.Configuration,builder.Environment);

builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = true,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
        ValidIssuer = jwtSection["Issuer"],
        ValidAudience = jwtSection["Audience"],
        IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),
        ClockSkew = TimeSpan.Zero,
        RequireExpirationTime = true, RequireSignedTokens = true,
        ValidAlgorithms = [Microsoft.IdentityModel.Tokens.SecurityAlgorithms.HmacSha256]
    };
});

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());
    });

// Learn more about configuring OpenAPI at https://aka.ms/aspnet/openapi
builder.Services.AddOpenApi();

var rawAllowedOrigins = builder.Configuration["ALLOWED_ORIGINS"]?.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries) 
                     ?? new[] { "https://fleetflow-frontend.azurewebsites.net", "http://localhost:5173", "http://localhost:5174", "http://127.0.0.1:5173", "http://127.0.0.1:5174", "http://localhost:3000" };
var allowedOrigins = rawAllowedOrigins.Select(o => o.TrimEnd('/')).Distinct().ToArray();

builder.Services.AddCors(options =>
{
    options.AddDefaultPolicy(policy =>
    {
        policy.WithOrigins(allowedOrigins)
              .AllowAnyHeader()
              .AllowAnyMethod()
              .AllowCredentials()
              .WithExposedHeaders("X-Total-Count", "X-Page", "X-Page-Size", "X-Total-Pages");
    });
});

var app = builder.Build();
app.UseMiddleware<FleetFlow.ServiceDefaults.ApiErrorsMiddleware>();

var readiness = app.Services.GetRequiredService<FleetReadiness>();

// Non-blocking background database initialization
_ = Task.Run(async () =>
{
    try
    {
        using (var scope = app.Services.CreateScope())
        {
            var dbContext = scope.ServiceProvider.GetRequiredService<FleetDbContext>();
            await dbContext.Database.EnsureCreatedAsync();

            // Idempotent Default Category Seeding
            var defaultCategories = new (string Name, string Description)[]
            {
                ("Executive Sedan", "Luxury and executive passenger sedans for corporate and premium mobility."),
                ("Full-Size SUV", "Spacious premium sport utility vehicles with high capacity and all-weather capability."),
                ("Commercial Cargo", "Heavy-duty cargo vans and commercial transport vehicles for logistics."),
                ("Compact EV", "High-efficiency 100% electric urban compact vehicles."),
                ("Premium Coupe", "High-performance premium sport and luxury coupes.")
            };

            bool hasChanges = false;
            foreach (var (name, description) in defaultCategories)
            {
                var exists = await dbContext.VehicleCategories.AnyAsync(c => c.Name.ToUpper() == name.ToUpper());
                if (!exists)
                {
                    dbContext.VehicleCategories.Add(new VehicleCategory
                    {
                        Id = Guid.NewGuid(),
                        Name = name,
                        Description = description
                    });
                    hasChanges = true;
                }
            }

            if (hasChanges)
            {
                await dbContext.SaveChangesAsync();
            }

            // Ensure feature tables exist on pre-existing databases.
            try
            {
                await dbContext.Database.ExecuteSqlRawAsync(@"
                    CREATE TABLE IF NOT EXISTS ""VehicleImages"" (
                        ""Id"" uuid NOT NULL PRIMARY KEY,
                        ""VehicleId"" uuid NOT NULL,
                        ""FileName"" character varying(255) NOT NULL,
                        ""OriginalFileName"" character varying(255) NOT NULL,
                        ""ContentType"" character varying(100) NOT NULL,
                        ""FileSize"" bigint NOT NULL,
                        ""RelativeUrl"" character varying(500) NOT NULL,
                        ""Caption"" character varying(255) NULL,
                        ""CreatedAt"" timestamp with time zone NOT NULL,
                        CONSTRAINT ""FK_VehicleImages_Vehicles_VehicleId"" FOREIGN KEY (""VehicleId"") REFERENCES ""Vehicles"" (""Id"") ON DELETE CASCADE
                    );
                    CREATE INDEX IF NOT EXISTS ""IX_VehicleImages_VehicleId"" ON ""VehicleImages"" (""VehicleId"");

                    CREATE TABLE IF NOT EXISTS ""Bookings"" (
                        ""Id"" uuid NOT NULL PRIMARY KEY,
                        ""CustomerId"" uuid NOT NULL,
                        ""VehicleId"" uuid NOT NULL,
                        ""StartDateTime"" timestamp with time zone NOT NULL,
                        ""EndDateTime"" timestamp with time zone NOT NULL,
                        ""Status"" character varying(50) NOT NULL,
                        ""TotalCost"" numeric(18, 2) NOT NULL,
                        ""CreatedAt"" timestamp with time zone NOT NULL,
                        ""UpdatedAt"" timestamp with time zone NULL,
                        CONSTRAINT ""FK_Bookings_Vehicles_VehicleId"" FOREIGN KEY (""VehicleId"") REFERENCES ""Vehicles"" (""Id"") ON DELETE RESTRICT
                    );
                    CREATE INDEX IF NOT EXISTS ""IX_Bookings_VehicleId"" ON ""Bookings"" (""VehicleId"");
                    CREATE INDEX IF NOT EXISTS ""IX_Bookings_CustomerId"" ON ""Bookings"" (""CustomerId"");
                    CREATE INDEX IF NOT EXISTS ""IX_Bookings_Status"" ON ""Bookings"" (""Status"");

                    CREATE TABLE IF NOT EXISTS ""MaintenanceRecords"" (
                        ""Id"" uuid NOT NULL PRIMARY KEY,
                        ""VehicleId"" uuid NOT NULL,
                        ""CreatedByUserId"" uuid NOT NULL,
                        ""ScheduledDateTime"" timestamp with time zone NOT NULL,
                        ""ServiceInformation"" character varying(2000) NOT NULL,
                        ""Details"" character varying(4000) NULL,
                        ""Cost"" numeric(18, 2) NOT NULL,
                        ""Status"" character varying(30) NOT NULL,
                        ""CreatedAt"" timestamp with time zone NOT NULL,
                        ""UpdatedAt"" timestamp with time zone NULL,
                        ""CompletedAt"" timestamp with time zone NULL,
                        CONSTRAINT ""FK_MaintenanceRecords_Vehicles_VehicleId"" FOREIGN KEY (""VehicleId"") REFERENCES ""Vehicles"" (""Id"") ON DELETE RESTRICT
                    );
                    CREATE INDEX IF NOT EXISTS ""IX_MaintenanceRecords_VehicleId"" ON ""MaintenanceRecords"" (""VehicleId"");
                    CREATE INDEX IF NOT EXISTS ""IX_MaintenanceRecords_Status"" ON ""MaintenanceRecords"" (""Status"");
                    CREATE INDEX IF NOT EXISTS ""IX_MaintenanceRecords_ScheduledDateTime"" ON ""MaintenanceRecords"" (""ScheduledDateTime"");
                ");
                await NotificationSchema.EnsureAsync(dbContext);
                await NotificationOutboxSchema.EnsureAsync(dbContext);
                await ReservationSchema.EnsureAsync(dbContext);
                await MaintenancePlanningSchema.EnsureAsync(dbContext);
                readiness.MarkInitialized();
                Console.WriteLine("[Database] FleetService database initialized and ready.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[Startup Warning] Table check: {ex.Message}");
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[Startup Warning] Database initialization deferred: {ex.Message}");
    }
});

