static string GetDatabaseConnectionString(IConfiguration configuration)
{
    var connStr = configuration.GetConnectionString("DefaultConnection") 
                  ?? configuration["ConnectionStrings__DefaultConnection"];
    if (!string.IsNullOrEmpty(connStr))
    {
        if (!connStr.Contains("Trust Server Certificate", StringComparison.OrdinalIgnoreCase))
        {
            connStr = connStr.TrimEnd(';') + ";Trust Server Certificate=true;";
        }
        if (!connStr.Contains("Timeout", StringComparison.OrdinalIgnoreCase))
        {
            connStr = connStr.TrimEnd(';') + ";Timeout=10;Command Timeout=30;";
        }
        return connStr;
    }

    var host = configuration["DB_HOST"] ?? "localhost";
    var port = configuration["DB_PORT"] ?? "5432";
    var user = configuration["DB_USER"] ?? "postgres";
    var password = configuration["DB_PASSWORD"] ?? "your_password_here";
    var dbName = configuration["FLEET_DB_NAME"] ?? "fleetflow_fleet";

    var isExplicitSsl = string.Equals(configuration["DB_SSL"], "true", StringComparison.OrdinalIgnoreCase);
    var isRemoteHost = !host.Equals("localhost", StringComparison.OrdinalIgnoreCase) && !host.Equals("127.0.0.1");
    var requiresSsl = isExplicitSsl || (isRemoteHost && (host.Contains("azure.com", StringComparison.OrdinalIgnoreCase) || host.Contains("postgres", StringComparison.OrdinalIgnoreCase) || host.Contains("database", StringComparison.OrdinalIgnoreCase)));

    var sslMode = requiresSsl ? ";Ssl Mode=Require;Trust Server Certificate=true" : "";
    return $"Host={host};Port={port};Database={dbName};Username={user};Password={password}{sslMode};Timeout=10;Command Timeout=30;";
}

using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using FleetFlow.Contracts;
using FleetFlow.ServiceDefaults;
namespace FleetService.Api.Services;
public sealed class MaintenanceStaffUnavailableException : Exception;
public interface IMaintenanceStaffDirectory
{
    Task<IReadOnlyList<MaintenanceStaffAccount>> ListAsync(CancellationToken ct);
    Task<MaintenanceStaffAccount?> GetAsync(Guid id, CancellationToken ct);
}
public sealed class MaintenanceStaffDirectory(HttpClient http, IServiceTokenProvider tokens) : IMaintenanceStaffDirectory
{
    private async Task<T?> Send<T>(string path, CancellationToken ct)
    {
        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, path);
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", await tokens.GetTokenAsync(ct));
            using var response = await http.SendAsync(request, ct);
            if (response.StatusCode == HttpStatusCode.NotFound) return default;
            if (!response.IsSuccessStatusCode) throw new MaintenanceStaffUnavailableException();
            return await response.Content.ReadFromJsonAsync<T>(ct) ?? throw new MaintenanceStaffUnavailableException();
        }
        catch (Exception ex) when (ex is HttpRequestException or System.Text.Json.JsonException or InvalidOperationException || ex is OperationCanceledException && !ct.IsCancellationRequested)
        { throw new MaintenanceStaffUnavailableException(); }
    }
    public async Task<IReadOnlyList<MaintenanceStaffAccount>> ListAsync(CancellationToken ct)
    {
        var accounts = await Send<List<MaintenanceStaffAccount>>("internal/staff/maintenance", ct) ?? throw new MaintenanceStaffUnavailableException();
        if (accounts.Count > 1000 || accounts.Any(a => a.Id == Guid.Empty || string.IsNullOrWhiteSpace(a.Username)) || accounts.Select(a => a.Id).Distinct().Count() != accounts.Count) throw new MaintenanceStaffUnavailableException();
        return accounts;
    }
    public async Task<MaintenanceStaffAccount?> GetAsync(Guid id, CancellationToken ct)
    {
        var account = await Send<MaintenanceStaffAccount>($"internal/staff/maintenance/{id}", ct);
        if (account != null && (account.Id != id || string.IsNullOrWhiteSpace(account.Username))) throw new MaintenanceStaffUnavailableException();
        return account;
    }
}

using System.Globalization;
using System.Text;
using System.Text.Json;
using FleetService.Api.Dtos;
namespace FleetService.Api.Services;

public static class ReportCsv
{
    public static byte[] Bookings(BookingExportResponse report) => Encode(
        ["Booking ID", "Customer ID", "Vehicle ID", "License plate", "Make", "Model", "Status",
         "Starts (UTC)", "Ends (UTC)", "Reserved amount (LKR)", "Created (UTC)", "Updated (UTC)"],
        report.Items.Select(r => new object?[] { r.BookingId, r.CustomerId, r.VehicleId, r.LicensePlate,
            r.Make, r.Model, r.Status.ToString(), r.StartDateTime, r.EndDateTime, r.TotalCost, r.CreatedAt, r.UpdatedAt }));

    public static byte[] Maintenance(MaintenanceReportResponse report)
    {
        if (!report.WorkOrders.Available) throw new TimeoutException("Maintenance report source unavailable.");
        if ((long)report.CurrentVehicles.Count + report.WorkOrders.Records.Count > BookingExportQuery.MaxRows)
            throw new ArgumentException("Maintenance export exceeds the supported row limit.");
        var vehicles = report.CurrentVehicles.Select(v => new object?[] { "Current vehicle", v.VehicleId,
            v.VehicleId, v.LicensePlate, v.Make, v.Model, v.HubLocation, v.Mileage, v.Status.ToString(),
            null, null, null, null, v.LastVehicleUpdateAt, null });
        var activities = report.WorkOrders.Records.Select(r => new object?[] { "Maintenance activity", r.MaintenanceId,
            r.VehicleId, r.LicensePlate, null, null, null, null, r.Status, r.Activity,
            r.ScheduledAt, r.CompletedAt, r.Cost, null, JsonSerializer.Serialize(r.History) });
        return Encode(["Record type", "Record ID", "Vehicle ID", "License plate", "Make", "Model", "Hub",
            "Mileage (km)", "Status", "Activity", "Scheduled (UTC)", "Completed (UTC)", "Recorded cost (LKR)",
            "Last vehicle update (UTC)", "History (JSON)"], vehicles.Concat(activities));
    }

    public static byte[] Encode(string[] headers, IEnumerable<object?[]> rows)
    {
        var content = new StringBuilder("\uFEFF"); // Excel-compatible UTF-8 BOM.
        void Line(IEnumerable<object?> cells) => content.AppendJoin(',', cells.Select(Cell)).Append("\r\n");
        Line(headers);
        foreach (var row in rows) Line(row);
        return Encoding.UTF8.GetBytes(content.ToString());
    }

    private static string Cell(object? value)
    {
        var text = value switch {
            null => "",
            DateTime time => (time.Kind == DateTimeKind.Unspecified ? DateTime.SpecifyKind(time, DateTimeKind.Utc) : time.ToUniversalTime()).ToString("O", CultureInfo.InvariantCulture),
            IFormattable number => number.ToString(null, CultureInfo.InvariantCulture) ?? "",
            _ => value.ToString() ?? ""
        };
        if (value is string)
        {
            var first = text.SkipWhile(c => char.IsWhiteSpace(c) || char.IsControl(c)).FirstOrDefault();
            // Quoted tab prefix makes formula-looking user text literal for Excel viewing.
            // Keep actual numeric values numeric; never turn an untrusted string into a formula.
            if ("=+-@＝＋－＠".Contains(first) || text.StartsWith('\t') || text.StartsWith('\r') || text.StartsWith('\n')) text = "\t" + text;
        }
        return "\"" + text.Replace("\"", "\"\"") + "\"";
    }
}

